/// Generic query result with execution metadata
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QueryResult<T> {
    pub data: Vec<T>,
    pub execution_time_ms: u64,
    pub rows_examined: usize,
    pub cache_hit: bool,
}

impl<T> QueryResult<T> {
    pub fn new(
        data: Vec<T>,
        execution_time_ms: u64,
        rows_examined: usize,
        cache_hit: bool,
    ) -> Self {
        Self {
            data,
            execution_time_ms,
            rows_examined,
            cache_hit,
        }
    }
}

